+const RARITIES=['Common','Uncommon','Rare','Epic','Legendary','Mythic','Divine','Cosmic','Transcendent'];
+const RARITY_COLORS=['#aab5ac','#8ed49d','#68b9e3','#bd8be8','#e8c77d','#e49af0','#f19d9d','#86e1ef','#e5f1a4'];
+const ARTIFACT_NAMES=['Seed of First Light','Mossclock','The Patient Spore','Root of Return','Aether Lens','Verdant Compass','Echoing Husk','Crown of Small Things','Tideglass','Fossil Heart','Unwritten Genome','Lantern of Elsewhere','The Long Spring','Cradle of Sparks','Living Equation','Woven Horizon','Starfall Kernel','Symbiote’s Promise','Memory of Rain','The Green Testament','Quiet Singularity','Primal Constellation','Worldroot Shard','Dreaming Cell','Eon Seed','Atlas of Becoming','The Last Beginning','Infinity Petal','Origin Engine','Primordia’s Eye'];
+const ARTIFACT_ICONS=['✧','⌛','◉','❋','◈','⌖','♧','♜','◌','♦','⌘','♢','☼','✦','∿','⌁','✷','❦','☂','❧','◉','✺','♧','❋','◈','▤','✶','❀','⚙','◎'];
+const GEAR_NAMES={Core:['Sporeheart','Verdant nucleus','Prism gland','Aether reactor','Worldseed core'],Shell:['Mossweave mantle','Glassbark carapace','Cinderproof hide','Starwoven scales','Elderbloom aegis'],Relic:['Forager’s charm','Rootbound talisman','Echoing fang','Comet-thread loop','Genesis sigil']};
+const GEAR_ICONS={Core:'◉',Shell:'⬡',Relic:'✧'};
+const UPGRADES=[{name:'Spore harvesters',desc:'Tiny helpers gather biomass over time.',icon:'♧',base:15,gain:0.5},{name:'Nutrient lattice',desc:'A living network boosts passive growth.',icon:'⌘',base:130,gain:4},{name:'Symbiotic colony',desc:'A thriving ecosystem multiplies production.',icon:'✺',base:1150,gain:28}];
+const $=id=>document.getElementById(id); const fmt=n=>{if(!Number.isFinite(n))return '∞';if(n<1000)return Math.floor(n).toLocaleString();const units=['K','M','B','T','Qa','Qi'];let i=-1;while(n>=1000&&i<units.length-1){n/=1000;i++}return n.toFixed(n<10?2:1)+units[i]};
+const fresh=()=>({biomass:0,genome:0,essence:0,level:0,run:0,total:0,ascensions:0,mutations:0,upgrades:[0,0,0],ownedForms:[0],artifacts:[],gear:[],equipped:{Core:null,Shell:null,Relic:null},last:Date.now(),sound:false});
+let s=fresh(),toastTimer;
+function load(){try{const raw=JSON.parse(localStorage.getItem('primordia-save'));if(raw&&typeof raw==='object'){s={...fresh(),...raw,upgrades:Array.isArray(raw.upgrades)?raw.upgrades:[0,0,0],ownedForms:Array.isArray(raw.ownedForms)?raw.ownedForms:[0],artifacts:Array.isArray(raw.artifacts)?raw.artifacts:[],gear:Array.isArray(raw.gear)?raw.gear:[],equipped:raw.equipped||{Core:null,Shell:null,Relic:null}};const elapsed=Math.min(8*3600,Math.max(0,(Date.now()-(s.last||Date.now()))/1000));if(elapsed>2){s.biomass+=elapsed*rate();setTimeout(()=>notify(`Welcome back — ${fmt(elapsed)}s of growth gathered.`),300)}}}catch{}s.last=Date.now()}
+function save(){s.last=Date.now();try{localStorage.setItem('primordia-save',JSON.stringify(s))}catch{}}
+function currentForm(){return Math.min(49,Math.floor(s.run/20))}function stage(){return Math.min(19,s.run%20)}function rarityIndex(){let r=currentForm();let chance=Math.random();return Math.min(8,Math.floor(Math.pow(Math.max(.02,r/49),.72)*8)+(chance<.12?1:0))}
+function bonus(){let total=s.mutations*.1;for(const a of s.artifacts)total+=a.bonus||0;for(const g of Object.values(s.equipped))if(g)total+=g.bonus||0;return total}
+function rate(){let raw=s.upgrades.reduce((sum,l,i)=>sum+l*UPGRADES[i].gain,0);return raw*(1+bonus())*(1+s.essence*.04)}
+function clickGain(){return (1+s.upgrades.reduce((sum,l,i)=>sum+l*(i+1)*2,0))*(1+bonus())*(1+s.essence*.04)}
+function stageCost(){return Math.floor(100*Math.pow(1.37,s.run)*Math.pow(1.13,s.ascensions))}
+function mutationCost(){return Math.ceil(1*Math.pow(1.72,s.mutations))}
+function gainEssence(){return s.run<199?0:Math.floor(Math.sqrt(s.run/20)*(1+s.ascensions*.16))}
