function notify(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function makeLoot(){const r=rarityIndex(),slot=['Core','Shell','Relic'][Math.floor(Math.random()*3)],form=currentForm(),name=GEAR_NAMES[slot][Math.floor(Math.random()*GEAR_NAMES[slot].length)];return {id:Date.now()+Math.random(),slot,name,rarity:r,form,bonus:(r+1)*.025+form*.002}}
function onEvolve(){const oldForm=currentForm(),oldStage=stage();s.run++;s.total++;const newForm=currentForm(),newStage=stage();if(!s.ownedForms.includes(newForm))s.ownedForms.push(newForm);if(newStage===0&&newForm!==oldForm){const gear=makeLoot();s.gear.push(gear);let equipped=s.equipped[gear.slot];if(!equipped||gear.rarity>equipped.rarity){s.equipped[gear.slot]=gear;notify(`New lifeform: ${FORMS[newForm]} · ${RARITIES[gear.rarity]} ${gear.slot} equipped!`)}else notify(`New lifeform: ${FORMS[newForm]} · found ${RARITIES[gear.rarity]} ${gear.slot}`);if(Math.random()<.58){const unlocked=ARTIFACT_NAMES.filter((_,i)=>!s.artifacts.some(a=>a.index===i));if(unlocked.length){const index=unlocked[Math.floor(Math.random()*unlocked.length)],rarity=Math.min(8,Math.max(0,gear.rarity+Math.floor(Math.random()*3)-1));const artifact={id:Date.now()+Math.random(),index,name:ARTIFACT_NAMES[index],icon:ARTIFACT_ICONS[index],rarity,bonus:(rarity+1)*.045};s.artifacts.push(artifact);notify(`Artifact discovered: ${artifact.name} · ${RARITIES[rarity]}!`)}}}else notify(`Adaptation ${String(s.run).padStart(3,'0')}: ${STAGES[newStage]}`);s.biomass=Math.max(0,s.biomass-stageCost());render();save()}
function buyUpgrade(i){const cost=Math.floor(UPGRADES[i].base*Math.pow(1.62,s.upgrades[i]));if(s.biomass<cost)return;s.biomass-=cost;s.upgrades[i]++;render();save()}
function mutate(){const cost=mutationCost();if(s.genome<cost)return;s.genome-=cost;s.mutations++;notify('Metabolism permanently accelerated.');render();save()}
function ascend(){const gain=gainEssence();if(!gain)return;openModal(`<h2>Begin a new cycle?</h2><p>Your organism will return to its first form, but your discoveries will reshape every future life.</p><div class="ascend-copy"><strong>Kept:</strong> Essence, artifacts, equipment, mutations, lifetime discoveries.<br><strong>Reset:</strong> Biomass, Genome, this cycle’s upgrades and forms.<div class="ascend-gain"><span>Essence gained</span><strong>✧ ${fmt(gain)}</strong></div></div><div class="modal-actions"><button onclick="closeModal()">Stay in this cycle</button><button class="confirm" id="confirmAscend">Ascend</button></div>`);$('confirmAscend').onclick=()=>{s.essence+=gain;s.ascensions++;s.biomass=0;s.genome=0;s.run=0;s.upgrades=[0,0,0];s.ownedForms=[0];closeModal();notify(`Rebirth complete · +${gain} Essence`);render();save()}}
function render(){const form=currentForm(),st=stage(),cost=stageCost(),gain=gainEssence();$('biomass').textContent=fmt(s.biomass);$('genome').textContent=fmt(s.genome);$('essence').textContent=fmt(s.essence);$('species').textContent=FORMS[form];$('speciesIndex').textContent=`LIFEFORM ${String(form+1).padStart(2,'0')} / 50`;$('stageName').textContent=`Stage ${st+1} · ${STAGES[st]}`;$('stageChip').textContent=`ADAPTATION ${String(s.run+1).padStart(3,'0')} / 1,000`;$('progressText').textContent=`${fmt(s.biomass)} / ${fmt(cost)} biomass`;$('progressFill').style.width=progress()+'%';$('nextEvolution').textContent=STAGE_NOUN[st];$('rate').innerHTML=`${fmt(rate())} <span class="stat-unit">/ s</span>`;$('clickYield').textContent=`+${fmt(clickGain())} biomass`;$('adaptations').innerHTML=`${Math.max(1,s.total)} <span class="stat-unit">/ 1,000</span>`;$('ascensionCount').innerHTML=`${s.ascensions} <span class="stat-unit">cycles</span>`;$('lifetime').textContent=`${Math.min(1000,Math.max(1,s.total))} / 1,000`;$('mutationCost').textContent=fmt(mutationCost());$('mutationLevel').textContent=`· Lv. ${s.mutations}`;$('mutationBonus').textContent=`+${Math.round(s.mutations*10)}%`;$('upgradeMultiplier').textContent=`×${(1+bonus()).toFixed(2)} output`;$('mutateBtn').disabled=s.genome<mutationCost();$('ascendGain').textContent=`+${fmt(gain)} essence`;$('ascendBtn').disabled=!gain;$('ascendHint').textContent=gain?`A new cycle yields ${fmt(gain)} Essence and +4% production per Essence.`:'Reach adaptation 200 (lifeform 10) to unlock rebirth.';$('artifactCount').textContent=`${s.artifacts.length}/30`; $('artifactVaultBadge').textContent=`${s.artifacts.length} discovered`;$('codexProgress').textContent=`${s.ownedForms.length} / 50 forms`;$('upgradeList').innerHTML=UPGRADES.map((u,i)=>{const level=s.upgrades[i],price=Math.floor(u.base*Math.pow(1.62,level));return `<div class="upgrade"><div class="upgrade-icon">${u.icon}</div><div><div class="upgrade-name">${u.name} <span style="color:#809087;font-size:10px">Lv. ${level}</span></div><div class="upgrade-desc">${u.desc} <b style="color:#a7dca3">+${fmt(u.gain)}/s</b></div></div><div class="upgrade-cost">${fmt(price)} biomass<br><button class="buy-btn" onclick="buyUpgrade(${i})" ${s.biomass<price?'disabled':''}>Cultivate</button></div></div>`}).join('');renderGear();renderArtifacts();renderCodex();$('soundBtn').textContent=s.sound?'♫ Sound on':'♫ Sound off'}
function renderGear(){const slots=['Core','Shell','Relic'];$('gearSlots').innerHTML=slots.map(slot=>{const g=s.equipped[slot];return `<div class="gear-slot"><div class="gear-icon">${GEAR_ICONS[slot]}</div><div><strong>${slot} · ${g?g.name:'Unformed'}</strong><small class="${g?'':'gear-empty'}">${g?`<span style="color:${RARITY_COLORS[g.rarity]}">${RARITIES[g.rarity]}</span> · +${Math.round(g.bonus*100)}% production`:'Waiting for an evolved form'}</small></div></div>`}).join('')}
function renderArtifacts(){const all=ARTIFACT_NAMES.map((name,i)=>{const a=s.artifacts.find(x=>x.index===i);return `<div class="catalog-item ${a?'':'locked'}"><div class="catalog-icon" style="color:${a?RARITY_COLORS[a.rarity]:'#718078'}">${ARTIFACT_ICONS[i]}</div><div><strong>${a?name:'???'}</strong><small>${a?`${RARITIES[a.rarity]} · +${Math.round(a.bonus*100)}% production`:'Discover through evolution'}</small></div></div>`});$('artifactGrid').innerHTML=all.join('')}
function renderCodex(){ $('codexGrid').innerHTML=FORMS.map((name,i)=>{const owned=s.ownedForms.includes(i),highest=owned?(i===currentForm()?stage()+1:20):0;return `<div class="catalog-item ${owned?'':'locked'}"><div class="catalog-icon">${owned?'◉':'?'}</div><div><strong>${owned?String(i+1).padStart(2,'0')+' · '+name:'Undiscovered lifeform'}</strong><small>${owned?`${highest} / 20 stages recorded`:`Form ${String(i+1).padStart(2,'0')} · unlock by evolving`}</small></div></div>`}).join('')}
function openModal(html){$('modalContent').innerHTML=html;$('modal').classList.add('open')}function closeModal(){$('modal').classList.remove('open')}
$('produceBtn').addEventListener('click',()=>{s.biomass+=clickGain();if(s.biomass>=stageCost())onEvolve();else{render();save()}});$('mutateBtn').addEventListener('click',mutate);$('ascendBtn').addEventListener('click',ascend);$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closeModal()});document.querySelectorAll('.nav-btn').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b===btn));document.querySelectorAll('.collection-view').forEach(v=>v.classList.remove('active'));$(btn.dataset.view+'View').classList.add('active')}));$('soundBtn').addEventListener('click',()=>{s.sound=!s.sound;render();save()});
load();render();setInterval(()=>{let r=rate();if(r>0){s.biomass+=r;while(s.run<1000&&s.biomass>=stageCost())onEvolve();render()}save()},1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){const dt=Math.min(8*3600,Math.max(0,(Date.now()-s.last)/1000));if(dt>2)s.biomass+=rate()*dt;render();save()}});
</script>

